fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Check if the string is empty
    if txt.is_empty() {
        return false;
    }

    // Get the last character
    let last_char = txt.chars().last().unwrap(); // Safe to unwrap since we checked for empty

    // Check if the last character is an ASCII letter
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // If the string has only one character, return true
    if txt.len() == 1 {
        return true;
    }

    // Check if the character before the last is a space
    let second_last_char = txt.chars().nth(txt.len() - 2).unwrap(); // Safe to unwrap since len > 1
    second_last_char == ' '
}